function first<T>(items: T[]): T | undefined {
  return items[0];
}

function wrap<T>(value: T): { value: T } {
  return { value: value };
}

function pickBiggest<T extends { price: number }>(items: T[]): T | undefined {
  let best: T | undefined = first(items);
  for (const item of items) {
    if (best === undefined || item.price > best.price) {
      best = item;
    }
  }
  return best;
}

